add_filter( 'woocommerce_product_categories_widget_args', 'perfectpixel_hide_categories_from_widget' );
add_filter( 'woocommerce_product_categories_widget_dropdown_args', 'perfectpixel_hide_categories_from_widget' );

function perfectpixel_hide_categories_from_widget( $args ) {
	$exclude = wp_parse_id_list( '{{widget_hidden_category_ids}}' );
	if ( 'yes' === '{{widget_hide_current}}' && function_exists( 'is_product_category' ) && is_product_category() ) {
		$exclude[] = get_queried_object_id();
	}
	if ( $exclude ) {
		$current         = isset( $args['exclude'] ) ? wp_parse_id_list( $args['exclude'] ) : array();
		$args['exclude'] = implode( ',', array_unique( array_merge( $current, $exclude ) ) );
	}
	return $args;
}
